window.BG3_PERMANENT = [
  {"n":"Auntie Ethel's Hair","a":1,"x":"gain +1 to an ability score of choice. Can be raised above 20.","h":"Defeat Auntie Ethel during Save Mayrina and take the hag's deal (or force one upon her) to spare Ethel's life."},
  {"n":"Awakened","a":1,"x":"use all illithid powers as a bonus action.","h":"Succeed at all three saving throws with the Zaith'isk in the infirmary of Crèche Y'llek, causing it to explode. The saves are significantly easier if the player character is in the device rather than Lae'zel. Failing any of the saving throws for the Zaith'isk…"},
  {"n":"BOOOAL's Benediction","a":1,"x":"gain advantage on attack rolls against Bleeding targets.","h":"Sacrifice a companion to BOOOAL in The Festering Cove (hirelings cannot be sacrificed). The effect is granted to all present party members, but is removed if all Kuo-toa in the Cove are killed. Alternatively, a party member can pickpocket the Sickle of BOOOAL…"},
  {"n":"Brand of the Absolute","a":1,"x":"allows the benefits from Absolute equipment and unlocks unique dialogue options when speaking to followers of the Absolute.","h":"Agree to let a character be branded by Gut in the Goblin Camp. Multiple characters can receive the brand after the first has been branded by Gut and then speaking to Warlock Greez."},
  {"n":"Find Familiar: Scratch","a":1,"x":"gain the ability to summon Scratch as a familiar while outside of camp. While summoned, Scratch is able to uncover buried treasure.","h":"Leave Scratch with the scent of the interacting party member so he joins them at camp. Later when he offers a ball, throw it to play fetch with him. Having Scratch's Ball in a party member's inventory allows use of Find Familiar: Scratch."},
  {"n":"Find Familiar: Cheeky Quasit","a":1,"x":"summon Shovel (or Basket, or Fork), the Cheeky Quasit.","h":"Find the unique Scroll of Summon Quasit in one of the coffins of the hidden area in the Apothecary's Cellar beneath the Blighted Village. Wizards can transcribe this spell, while other spellcasting classes (Sorcerer, Wizard, or Warlock) may acquire the abilit…"},
  {"n":"Instrument proficiency","a":1,"x":"know how to play a variety of musical instruments and be able to entertain a crowd with them, including for small amounts of gold.","h":"Pass one of two Charisma (Performance) checks while helping Alfira with her song in the Emerald Grove. As Bards already have this proficiency, the meeting with Alfira provides no additional benefit to them."},
  {"n":"Loviatar's Love","a":1,"x":"gain a +2 bonus to attack rolls and Wisdom saving throws if the party member with this passive has 30% Hit Points or less.","h":"Submit to Abdirak and put on a good performance for him in the Shattered Sanctum. Note: This condition is specifically coded to be lost upon character death."},
  {"n":"Necromancy of Thay","a":1,"x":"gain the passive feature Forbidden Knowledge, which grants a +1 to Wisdom saving throws and ability checks. The character with this bonus may also cast Speak with Dead once per long rest.","h":"Turn all three pages while reading Necromancy of Thay, a book found in a hidden area in the Apothecary's Cellar beneath the Blighted Village. Turning just the first page grants Speak with Dead. The reader need not succeed any of the saving throws associated w…"},
  {"n":"Paid the Price","a":1,"x":"gain a +1 bonus to Intimidation checks, but also disadvantage on Perception checks. Additionally, gain disadvantage when attacking Hags. This permanently changes the appearance of the chosen's right or left eye. It cannot be reversed using the Magic Mirror, and is mutually exclusive with Volo’s Ers…","h":"Accept Auntie Ethel's deal to remove the parasite at the Riverside Teahouse."},
  {"n":"Survival Instinct","a":1,"x":"gain the additional illithid power Survival Instinct, which allows the user to infuse a creature with psionic force, healing them if they reach 0 hit points.","h":"Complete the quest Help Omeluum investigate the parasite with Omeluum in the Underdark. This is a unique illithid power and cannot be obtained through regular illithid power progression."},
  {"n":"Volo's Ersatz Eye","a":1,"x":"gain a permanent See Invisibility effect. This permanently changes the appearance of the chosen's right eye most closely to \"Blue 3\". It cannot be reversed using the Magic Mirror and is mutually exclusive with Paid the Price.","h":"Rescue Volo from the Goblin Camp. When the character speaks to him in the campsite afterwards, they must tell him about their Tadpole infection and complete his experimental 'surgery'."},
  {"n":"Arabella's Shadow Entangle","a":2,"x":"gain the ability to entangle an Undead or Shadow Creature.","h":"Tell Arabella about her parents' fate during the quest Find Arabella's Parents."},
  {"n":"Improved Bardic Inspiration","a":2,"x":"gain a charge of Bardic Inspiration that is stronger than usual (1d12). Usable once per long rest, and does not consume Bardic Inspiration charges. This bonus does not strengthen existing Bardic Inspiration uses (if any) they remain at the appropriate strength for the character's Bard level.","h":"At the end of Act Two, if Alfira is still alive, she moves to Moonrise Towers. Talking with her reveals that she wants to use music to cheer up the tiefling children in the room with her. If the active character is a Bard, they can speak with her again to gai…"},
  {"n":"Githzerai Mind Barrier","a":2,"x":"gain advantage on Intelligence saving throws.","h":"Insert the Waking Mind (found at 750 after the brain connect puzzle in the Mind Flayer Colony) into the nearby Mind-Archive Interface. Speak to the Slack-Skinned Head, and agree to purge or consume its mind. Note: This condition is lost upon character death (…"},
  {"n":"Consumed Shadow Weave","a":2,"x":"Gale gains an additional level three spell slot, separate from normal spell slots. Recharges per long rest.","h":"Only available to Gale while playing his origin, not as a companion. Consume the Shadow Weave from the corpse of Gerringothe Thorm, Malus Thorm or Thisobald Thorm after slaying them in combat. Cleansing the Shadow Weave grants Mystra's Blessing until Long res…"},
  {"n":"Potion of Everlasting Vigour","a":2,"x":"gain +2 Strength. Can be used to raise Strength above 20. This remains after respeccing the character.","h":"Convince Astarion to bite Araj Oblodra in Moonrise Towers."},
  {"n":"Slayer Form","a":2,"x":"gain the ability to transform into the Slayer once per long rest.","h":"Only available while playing the Dark Urge Origin. Kill either Isobel, their lover, or the companion with the highest approval toward them, as part of The Urge quest. Alternatively, it can be acquired alongside the one-time-use spell Power Word Kill by agreei…"},
  {"n":"Summon Us","a":2,"x":"summon Us, an intellect devourer, as a familiar.","h":"Free Us and prevent it from dying on the Nautiloid during the Prologue, then free it from its cage in the Mind Flayer Colony towards the end of Act Two. Pacifying Us on the Nautiloid via skill checks will cause the resulting debuffs to remain with it the rest…"},
  {"n":"Anointed in Splendour","a":3,"x":"gain +2 bonus to all Saving Throws.","h":"Offer enough gold to one of the deities in the Stormshore Tabernacle to ask for a blessing. The exact amount of gold required depends on the character's level and the difficulty settings. This can be done for every character, but an offering must be made for…"},
  {"n":"Partial Ceremorphosis","a":3,"x":"gain access to tier 3 illithid powers, and automatically unlock all tier 1 illithid powers and the tier 3 illithid power Fly. This causes an irrevocable cosmetic change in the character. Any tadpoles used to obtain tier 1 illithid powers prior to this point are refunded if this bonus is acquired.","h":"Consume the Astral-Touched Tadpole offered by the Emperor."},
  {"n":"Danse Macabre","a":3,"x":"create 4 ghouls that fight alongside the character. This passive comes with a curse which lowers the character's Constitution by 5, but can be removed with the Remove Curse spell while keeping Danse Macabre.","h":"Read The Tharchiate Codex (found at the end of the Vault puzzle in Ramazith's Tower), then read the last page of the Necromancy of Thay (from Act 1) and pass a DC 20 Wisdom Saving Throw."},
  {"n":"Tasha's Hideous Laughter/Monk's Hideous Laughter","a":3,"x":"gain the ability to cast Tasha's Hideous Laughter once per long rest.","h":"Carry the Sentient Amulet from Grymforge to a casket under the Open Hand Temple in Wyrm's Crossing and complete Help the Cursed Monk. The party member must choose to accept the curse themself. Possible wisdom loss if the character fails Constitution/Wisdom sa…"},
  {"n":"Mirror of Loss","a":3,"x":"gain +2 to a chosen ability score (and optionally +1 to Charisma).","h":"The interacting character must successfully offer a prayer (Religion Check) to the Mirror of Loss in the House of Grief, then sacrifice one or more of their ability scores. It is possible to receive the option to choose a permanent +2 bonus to any ability, or…"},
  {"n":"Slayer Knowledge","a":3,"x":"gain advantage against Slayer abilities. When playing as the Dark Urge with the Slayer form unlocked, it also grants the Piercing Growl skill.","h":"Rescue Volo while he is tied up to explosives near the Steel Watch Foundry. Talk to him after the fight that ensues he then returns to camp. Back at camp, talk to him again. He then explains that he was targeted by the Lord of Murder Bhaal and his Chosen. The…"},
  {"n":"Sweet Stone Features","a":3,"x":"gain a +1d4 bonus to attack rolls and saving throws.","h":"Pay Boney in the Circus of the Last Days 5000 gold for Stoney to construct a statue of the player character or another party member. The effect goes to whomever is depicted. Stony can only construct one statue for the party. The effect begins after a long res…"},
  {"n":"The Tharchiate Codex: Blessing","a":3,"x":"gain 20 temporary hit points after a Long Rest. Remains active if The Tharchiate Codex is also used to obtain Danse Macabre.","h":"Read The Tharchiate Codex (found at the end of the Vault puzzle in Ramazith's Tower). Only available to the first character who reads the Codex."},
  {"n":"Unstable Blood","a":3,"x":"the player character's blood is now highly flammable if the bleed and creating a blood surface, it explodes upon contact with fire.","h":"Give the interacting party member's blood to Araj Oblodra in Moonrise Towers in Act 2, then meet her again east of The Blushing Mermaid in Act 3 and help her again. She then gives a potion that grants this feature after it is consumed."},
  {"n":"Vampire","a":3,"x":"Accepting a romanced Vampire Ascendant Astarion results in the gain of the class action Bite (Vampire Spawn) as well as access to the buff from Circle of Bones.","h":"Only available to certain characters who accept the offer to be turned into a vampire. Allow romanced Astarion to complete the ascension ritual and comply with the request to be turned into a vampire."},
  {"n":"Vampire Ascendant","a":3,"x":"Astarion gains class actions Ascendant Bite and Misty Escape (Vampire Ascendant), as well as an extra Necrotic damage on his weapon and unarmed attacks.","h":"Only available to Astarion (companion or origin). Defeat Cazador without killing any of his spawn (or at most one, in which case Cazador can take their place) while having Astarion in your party. Afterward, allow Astarion to complete the ascension ritual."}
];
